// Aggregator returns one record per user per device; reference_id is our students.id.
const SOURCES = ['apple', 'samsung', 'whoop', 'garmin'];
const rows = $input.all().flatMap(i => i.json.data || [])
  .filter(r => r.reference_id && SOURCES.includes(String(r.provider).toLowerCase()))
  .map(r => ({
    student_id: Number(r.reference_id),
    date: r.date,
    source: String(r.provider).toLowerCase(),
    active_min: r.active_minutes ?? null,
    strain: r.strain ?? null,
    sleep_hours: r.sleep_seconds != null ? Math.round(r.sleep_seconds / 36) / 100 : null,
    recovery_pct: r.recovery_score ?? null,
  }));
return [{ json: { count: rows.length, rows } }];
